def transform(grid):
    w = len(grid[0])
    seed = next(c for c, v in enumerate(grid[0]) if v == 2)
    out = [[0] * w for _ in range(w)]
    for r in range(w):
        left, right = seed - r, seed + r
        if 0 <= left < w:
            out[r][left] = 2
        if 0 <= right < w:
            out[r][right] = 2

        for c in range(w):
            if (c - r - seed) % 4 == 0:
                if r > max(seed, w - 1 - seed) or left <= c <= right:
                    if out[r][c] == 0:
                        out[r][c] = 1
    return out
